package com.exito.chop;
import org.tensorflow.lite.Interpreter;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
/** Local Basic Pitch inference. Actual musical notes; pad triggers are a different export. */
final class MidiTranscriber {
 static final int WINDOW=43844,HOP=36164,OUTPUT=172,PRE=3840;
 static final class Detector {final ArrayList<MidiIO.Note> notes=new ArrayList<>();final double[] start=new double[88],energy=new double[88],previous=new double[88],onsets=new double[88];final int[] gap=new int[88];Detector(){Arrays.fill(start,-1);}void frame(double time,double[] frame,double[] onset){for(int p=0;p<88;p++){double v=frame[p],o=onset[p];boolean attack=o>.5&&onsets[p]<=.5||v>.45&&previous[p]<.3;if(start[p]>=0&&attack&&v>=previous[p]&&time-start[p]>.09){finish(p,time);start[p]=time;energy[p]=v;}if(start[p]<0&&attack&&v>.22){start[p]=time;energy[p]=v;gap[p]=0;}if(start[p]>=0){energy[p]=Math.max(energy[p],v);if(v<.25)gap[p]++;else gap[p]=0;if(gap[p]>=3)finish(p,time-.023);}previous[p]=v;onsets[p]=o;}}void finish(int p,double time){if(start[p]>=0&&time-start[p]>=.055)notes.add(new MidiIO.Note(start[p],time,p+21,(int)Math.round(Math.min(1,Math.sqrt(energy[p]))*110)));start[p]=-1;gap[p]=0;}List<MidiIO.Note> finish(double end){for(int p=0;p<88;p++)finish(p,end);return notes;}}
 static List<MidiIO.Note> notes(Engine e,short[] pcm,int rate,int from,int to)throws Exception{byte[] bytes;try(InputStream in=e.context.getAssets().open("models/basic-pitch.tflite")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] block=new byte[8192];int n;while((n=in.read(block))>0)b.write(block,0,n);bytes=b.toByteArray();}ByteBuffer model=ByteBuffer.allocateDirect(bytes.length).order(ByteOrder.nativeOrder());model.put(bytes).rewind();ByteBuffer input=ByteBuffer.allocateDirect(WINDOW*4).order(ByteOrder.nativeOrder()),note=ByteBuffer.allocateDirect(OUTPUT*88*4).order(ByteOrder.nativeOrder()),onset=ByteBuffer.allocateDirect(OUTPUT*88*4).order(ByteOrder.nativeOrder()),contour=ByteBuffer.allocateDirect(OUTPUT*264*4).order(ByteOrder.nativeOrder());HashMap<String,Object> inputs=new HashMap<>(),outputs=new HashMap<>();inputs.put("input_2",input);outputs.put("note",note);outputs.put("onset",onset);outputs.put("contour",contour);Resampler resampler=new Resampler(rate,22050);int total=(int)Math.ceil((to-from)*22050./rate);Detector detector=new Detector();double[] f=new double[88],o=new double[88];try(Interpreter interpreter=new Interpreter(model,new Interpreter.Options().setNumThreads(2))){for(int at=0;at<total;at+=HOP){input.clear();for(int i=0;i<WINDOW;i++)input.putFloat((float)resampler.read(pcm,at-PRE+i,-1,from,to));input.rewind();note.rewind();onset.rewind();contour.rewind();interpreter.runSignature(inputs,outputs);for(int t=15;t<157;t++){double seconds=(at+(t-15)*HOP/142.)/22050.;if(seconds>(to-from)/(double)rate)break;for(int p=0;p<88;p++){f[p]=note.getFloat((t*88+p)*4);o[p]=onset.getFloat((t*88+p)*4);}detector.frame(seconds,f,o);}e.message("Basic Pitch · transcripción local · "+Math.min(100,(at+HOP)*100/Math.max(1,total))+" %");}}return detector.finish((to-from)/(double)rate);}
 static List<MidiIO.Note> clip(List<MidiIO.Note> notes,double start,double end){ArrayList<MidiIO.Note> out=new ArrayList<>();for(MidiIO.Note n:notes){double a=Math.max(start,n.start),b=Math.min(end,n.end);if(b>a)out.add(new MidiIO.Note(a-start,b-start,n.pitch,n.velocity));}return out;}
 static byte[] triggers(Engine e)throws IOException{ArrayList<MidiIO.Note> notes=new ArrayList<>();double step=15./e.slots.masterBpm;for(int i=0;i<16;i++)if(e.sequencer.source[i]>=0)notes.add(new MidiIO.Note(i*step,(i+1)*step,36+e.sequencer.pad[i],Math.max(1,Math.min(16,e.sequencer.level[i]))*7,e.sequencer.source[i]));return MidiIO.file(notes,e.slots.masterBpm,"Pads · canales 1–8 = fuentes; 36 = A01");}
 static void put(ZipOutputStream z,String name,byte[] bytes)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(bytes);z.closeEntry();}
 static void export(Engine e,int mode){if(!e.ready())return;if(mode==1&&!e.hasPad(e.selected)){e.message("Marca primero un pad.");return;}e.finishPadMarking(false);e.freezeForEdit();e.harmony.stop();e.sequencer.stop();e.drums.stop();final short[] pcm=e.rendered;final int rate=e.rate,index=e.selected,bpm=e.slots.masterBpm,count=e.padCount();final int[] from=new int[count],to=new int[count];double scale=pcm.length/(double)e.source.length;for(int i=0;i<count;i++){from[i]=(int)(e.start(i)*scale);to[i]=(int)(e.end(i)*scale);}e.busy=true;e.worker.execute(()->{try{File dir=new File(e.context.getCacheDir(),"exports");dir.mkdirs();File f;if(mode==3){f=new File(dir,"ChopGO_Disparos.mid");Files.write(f.toPath(),triggers(e));}else if(mode==1){f=new File(dir,"ChopGO_Chop_Notas.mid");Files.write(f.toPath(),MidiIO.file(notes(e,pcm,rate,from[index],to[index]),bpm,"Notas estimadas del chop"));}else{List<MidiIO.Note> notes=notes(e,pcm,rate,0,pcm.length/2);if(mode==0){f=new File(dir,"ChopGO_Fuente_Notas.mid");Files.write(f.toPath(),MidiIO.file(notes,bpm,"Basic Pitch · fuente completa"));}else{f=new File(dir,"ChopGO_Notas_y_Chops.zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){put(z,"Fuente_completa.mid",MidiIO.file(notes,bpm,"Fuente completa"));for(int i=0;i<count;i++)put(z,String.format(Locale.US,"Chops/Chop_%02d.mid",i+1),MidiIO.file(clip(notes,from[i]/(double)rate,to[i]/(double)rate),bpm,"Chop "+(i+1)));put(z,"Disparos_secuenciador.mid",triggers(e));put(z,"Instrumentos.mid",e.harmony.midi());put(z,"LEEME.txt","Notas estimadas localmente con Basic Pitch sobre el audio con tono/tempo aplicado y antes de FX creativos. No separa instrumentos de la mezcla: revisa falsas notas, octavas y duraciones. MIDI de chops inicia cada corte en cero. Disparos_secuenciador usa canales 1–8 para fuentes y notas 36–99 para pads; no contiene la melodía.".getBytes("UTF-8"));}}}e.busy=false;e.main.post(()->MainActivity.launch(e.context,"save-artifact",f.getName()));}catch(Throwable error){e.busy=false;e.message("MIDI: "+Engine.reason(error));}});}
}
